enum Perms {
    P_READ   = 1 << 0, // Binary 001
    P_WRITE  = 1 << 1, // Binary 010
    P_EXEC   = 1 << 2  // Binary 100
};

// Combining flags using bitwise OR (|)
int settings = P_READ | P_WRITE; // Value: 3 (0b011)

// Combining three flags
int full_access = P_READ | P_WRITE | P_EXEC; // Value: 7 (0b111)

// Check if a specific flag is present (using & operator)
bool can_write = (settings & P_WRITE) != 0;

